import { ORACLE_SEEDS } from "./corpus.js";
import { ENV, NOW, load, worldOf } from "./world.js";
import { applyPlan, standWith, storedIcs } from "./apply.js";

const seed = ORACLE_SEEDS.find((s) => s.name === "infinite-weekly-moscow")!;
const stand = standWith(seed);
const ics = stand.fake.ics(stand.path);
const o = load(ics);
const patch = {"reminders":[{"method":"display","minutesBefore":10},{"method":"email","minutesBefore":20}]};
const plan = planUpdate(o, { now: NOW, scope: "this_and_following", instanceStart: "2026-10-20T09:00:00+03:00", patch, confirm: false, etag: undefined, currentEtag: stand.etag });
verifyPlan(ics, plan, ENV, { now: NOW, patch }); // как зовёт оркестрация: с патчем
await applyPlan(stand, plan);
console.log(worldOf(storedIcs(stand)).snaps.map((s) => s.address + " " + s.summary));
// здесь расходится со смыслом scope: после записи напоминание письмом осталось без адресата (ATTENDEE): DISPLAY|-PT10M|START|;EMAIL|-PT20M|START|

